import React, { ReactElement } from 'react';

import {
  MARKER_RADIUS,
  OUTER_CIRCLE_RADIUS,
  OUTLINE_STROKE_WIDTH,
  PILL_MARKER_HEIGHT,
} from '../constants.js';

/**
 * Builds the marker shape depending on the width.
 * - Circle shape if width is 0
 * - Pill shape if width is provided
 *
 * @param widthProp -
 * @param x -
 * @param commonProps -
 * @param crop -
 */
export function buildMarkerShape({
  width,
  x,
  commonProps,
  shape,
  clipPathId,
}: {
  width: number;
  x: number;
  commonProps: Record<string, string | number>;
  shape: 'pill' | 'circle';
  clipPathId: string;
}) {
  let markerShape: ReactElement;

  if (shape === 'pill') {
    markerShape = (
      <rect
        data-testid="pill-marker"
        clipPath={`url(#${clipPathId})`}
        x={x}
        y={OUTLINE_STROKE_WIDTH}
        height={PILL_MARKER_HEIGHT}
        width={width}
        rx={MARKER_RADIUS}
        {...commonProps}
      />
    );
  } else {
    markerShape = (
      <circle
        data-testid="circle-marker"
        cx={x}
        cy={OUTER_CIRCLE_RADIUS}
        r={MARKER_RADIUS}
        {...commonProps}
      />
    );
  }

  return markerShape;
}
